// src/pages/AdminDashboard.jsx
import { useState, useEffect, useContext } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";

export default function AdminDashboard() {
  const { user } = useContext(AuthContext);
  const navigate = useNavigate();

  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [message, setMessage] = useState("");

  // Fetch initial data
  useEffect(() => {
    const fetchData = async () => {
      try {
        const stateRes = await api.get("/admin/voting-state");
        setVotingOpen(stateRes.data.votingOpen);

        const usersRes = await api.get("/admin/pending-users");
        setPendingUsers(usersRes.data);

        const candRes = await api.get("/candidates");
        setCandidates(candRes.data);
      } catch (err) {
        console.error("Failed to load dashboard data:", err);
      }
    };
    fetchData();
  }, []);

  const toggleVoting = async () => {
    try {
      const res = await api.post("/admin/toggle-voting");
      setVotingOpen(res.data.votingOpen);
      setMessage(`Voting is now ${res.data.votingOpen ? "OPEN" : "CLOSED"}`);
    } catch (err) {
      setMessage("Failed to toggle voting state");
    }
  };

  const approveUser = async (id) => {
    try {
      await api.post(`/admin/approve-user/${id}`);
      setPendingUsers((prev) => prev.filter((u) => u.id !== id));
      setMessage("User approved successfully");
    } catch (err) {
      setMessage("Failed to approve user");
    }
  };

  return (
    <div style={{ minHeight: "100vh", backgroundColor: "#f4f6f8", padding: "40px", fontFamily: "Arial, sans-serif" }}>
      {/* Header */}
      <header style={{ marginBottom: "30px", textAlign: "center" }}>
        <img src="/logo.png" alt="iVote Logo" style={{ height: "50px", marginBottom: "15px" }} />
        <h1 style={{ fontSize: "2rem", color: "#007bff", margin: 0 }}>Admin Dashboard</h1>
        <p style={{ color: "#555" }}>Manage users, candidates, and election settings</p>
      </header>

      {/* Voting Controls */}
      <div style={{
        maxWidth: "600px",
        margin: "0 auto 20px auto",
        padding: "20px",
        background: "#fff",
        borderRadius: "12px",
        boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
        textAlign: "center"
      }}>
        <h2 style={{ marginBottom: "15px", color: "#333" }}>Voting Controls</h2>
        <button
          onClick={toggleVoting}
          style={{
            padding: "12px 20px",
            borderRadius: "8px",
            border: "none",
            backgroundColor: votingOpen ? "#dc3545" : "#28a745",
            color: "#fff",
            fontWeight: "bold",
            cursor: "pointer"
          }}
        >
          {votingOpen ? "Close Voting" : "Open Voting"}
        </button>
      </div>

      {/* Pending Users */}
      <div style={{
        maxWidth: "800px",
        margin: "0 auto 20px auto",
        padding: "20px",
        background: "#fff",
        borderRadius: "12px",
        boxShadow: "0 4px 12px rgba(0,0,0,0.08)"
      }}>
        <h2 style={{ marginBottom: "15px", color: "#333" }}>Pending Users</h2>
        {pendingUsers.length === 0 ? (
          <p style={{ color: "#777" }}>No pending users</p>
        ) : (
          <ul style={{ listStyle: "none", padding: 0 }}>
            {pendingUsers.map((u) => (
              <li key={u.id} style={{ marginBottom: "10px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <span>{u.email}</span>
                <button
                  onClick={() => approveUser(u.id)}
                  style={{
                    padding: "6px 12px",
                    borderRadius: "6px",
                    border: "none",
                    backgroundColor: "#007bff",
                    color: "#fff",
                    cursor: "pointer"
                  }}
                >
                  Approve
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>

      {/* Candidates */}
      <div style={{
        maxWidth: "800px",
        margin: "0 auto 20px auto",
        padding: "20px",
        background: "#fff",
        borderRadius: "12px",
        boxShadow: "0 4px 12px rgba(0,0,0,0.08)"
      }}>
        <h2 style={{ marginBottom: "15px", color: "#333" }}>Registered Candidates</h2>
        {candidates.length === 0 ? (
          <p style={{ color: "#777" }}>No candidates registered</p>
        ) : (
          <ul style={{ listStyle: "none", padding: 0 }}>
            {candidates.map((c) => (
              <li key={c.id} style={{ marginBottom: "8px" }}>
                <strong>{c.name}</strong> — {c.position} {c.party && `(${c.party})`}
              </li>
            ))}
          </ul>
        )}
      </div>

      {/* Feedback Message */}
      {message && (
        <p style={{
          textAlign: "center",
          color: message.toLowerCase().includes("fail") ? "red" : "green",
          marginTop: "15px",
          fontWeight: "bold"
        }}>
          {message}
        </p>
      )}
    </div>
  );
}
